{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts and tool in storage, assemble fastening at workbench, leave tool on bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_location",
        "entity_kind": "FIXED_TARGET",
        "function": "Target area on the workbench where the fastening must occur.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["workbench surface", "tray"],
      "required_properties": ["is the target for fastening"]
      },
      {
        "id": "fastening_component",
        "entity_kind": "OBJECT",
        "function": "Hardware piece (screw, bolt, etc.) needed to secure the fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["screw", "bolt", "nut", "pin"],
      "required_properties": ["compatible with fastening_location"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Implement used to apply the fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["screwdriver", "wrench", "drill"],
      "required_properties": ["compatible with fastening_component"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the task is performed and tools are left.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
      "candidate_categories": ["wooden table", "desk"],
      "required_properties": ["flat surface", "stable support"]
      },
      {
        "id": "storage_containers",
        "entity_kind": "REGION",
        "function": "Enclosed spaces that may hold components or tools.",
        "required_count": 3,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": ["drawer", "cabinet"],
      "required_properties": ["enclosed space", "openable"]
      }
    ],
    "functional_relations": [
      {
        "id": "fastening_assembly",
        "relation": "The component must fit the location using the tool.",
        "participant_roles": [
          "fastening_location",
          "fastening_component",
          "fastening_tool"
        ]
      ,
      "required": true
      },
      {
        "id": "tool_placement",
        "relation": "The tool must be left on the workbench.",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "search_and_identify",
        "operation": "Inspect storage containers to find component and tool.",
        "participant_roles": [
          "storage_containers",
          "fastening_component",
          "fastening_tool"
        ],
        "operation_count": 1
      },
      {
        "id": "complete_fastening",
        "operation": "Apply component to location using tool.",
        "participant_roles": [
          "fastening_location",
          "fastening_component",
          "fastening_tool"
        ],
        "operation_count": 1
      },
      {
        "id": "leave_equipment",
        "operation": "Place tool on workbench.",
        "participant_roles": [
          "fastening_tool",
          "workbench"
        ],
        "operation_count": 1
      }
    ]
  }
  ,
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_location": [
        {
          "label": "Tray on desk",
          "visual_description": "Blue tray with yellow/grey blocks on the wooden surface."
        }
      ],
      "fastening_component": [],
      "fastening_tool": [],
      "workbench": [
        {
          "label": "Wooden Desk",
          "visual_description": "Brown wooden table with drawers underneath."
        }
      ],
      "storage_containers": [
        {
          "label": "Left Drawer",
          "visual_description": "Blue drawer with white handle under the left side of the desk."
        },
        {
          "label": "Right Drawer",
          "visual_description": "Blue drawer with white handle under the right side of the desk."
        },
        {
          "label": "Cabinet",
          "visual_description": "Blue cabinet with white handle on top of the desk."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "left_drawer",
        "label": "Left Drawer",
        "visual_description": "Blue drawer with white handle under the left side of the desk.",
        "reason": "Closed storage structure, likely contains small components or tools."
      },
      {
        "id": "right_drawer",
        "label": "Right Drawer",
        "visual_description": "Blue drawer with white handle under the right side of the desk.",
        "reason": "Closed storage structure, likely contains small components or tools."
      },
      {
        "id": "cabinet",
        "label": "Cabinet",
        "visual_description": "Blue cabinet with white handle on top of the desk.",
        "reason": "Closed storage structure, likely contains tools or components."
      }
    ],
    "inspection_order": [
      "left_drawer",
      "right_drawer",
      "cabinet"
    ]
  }
  ,
  "unsupported_reason": "",
  "schema_version": 3
}
